import React from "react";
import clsx from "clsx";
import { Container as ContainerStyles } from "@airbus/styles";
import { createUseStyles } from "../../lib/styling";
import { BreakpointName, CommonProps, PolymorphicProps } from "../helperTypes";

const useStyles = createUseStyles(ContainerStyles, "container");

type Props = {
  /**
   * If true, responsive max-widths will be set for all breakpoints
   */
  fixed?: boolean;
  /**
   * If provided, the container will be fullwidth until the given breakpoint
   */
  until?: BreakpointName;
};

export type ContainerProps<C extends React.ElementType> = PolymorphicProps<
  C,
  Props & CommonProps
>

export const Container = <C extends React.ElementType = "div">(
  props: ContainerProps<C>
) => {
  const {
    className,
    children,
    component,
    fixed = false,
    until,
    ...rest
  } = props;
  const ComponentProp = component || "div";
  const classes = useStyles();

  return (
    <ComponentProp
      className={clsx(
        className,
        !fixed && classes.root,
        fixed && classes.fixed,
        until && classes[`_until-${until}`]
      )}
      {...rest}
    >
      {children}
    </ComponentProp>
  );
};

export default Container;
